function Heading({title,subtitle,action}:{title:string;subtitle?:string;action?:React.ReactNode}){return <div className="heading"><div><span className="eyebrow">KAVACH AI WORKSPACE</span><h1>{title}</h1>{subtitle&&<p>{subtitle}</p>}</div>{action}</div>}
