function Pill({children}:{children:string}){let c=children.toLowerCase().includes("complete")?"success":children.toLowerCase().includes("progress")?"progress":children.toLowerCase().includes("review")?"info":children.toLowerCase().includes("overdue")?"danger":"warning";return <span className={`pill ${c}`}>{children}</span>}
